import numpy as np
from scipy import ndimage
x=np.load('source_pixels.npz')['rgb']
# list cyan, yellow bright, gray bright components per frame
for t in range(96):
 a=x[t].astype(int); r,g,b=np.moveaxis(a,2,0)
 masks={'cyan':(g>120)&(b>120)&(g>r*1.8),'yellow':(r>120)&(g>90)&(b<100)&(r>1.15*g),'white':(r>90)&(g>90)&(b>80)&(abs(r-g)<35)}
 vals=[]
 for name,m in masks.items():
  yy,xx=np.where(m)
  if len(xx): vals.append(name+':'+str((len(xx),round(xx.mean(),1),round(yy.mean(),1),xx.min(),yy.min(),xx.max(),yy.max())))
 if t<45 or t%10==0: print(t,*vals)
PY"
